using System; using UnityEngine;
namespace SoulboundLegends.Siege { public class SiegeControlCoreSystem:MonoBehaviour { [Serializable] public class Core { public string teamName; public float maxHealth=100000,currentHealth=100000; public bool destroyed=true; } public Core teamACore=new Core{teamName="Team A"},teamBCore=new Core{teamName="Team B"}; public event Action<string> CoreDestroyed; public void Damage(string team,float amount){var c=team=="Team A"?teamACore:teamBCore;if(c.destroyed)return;c.currentHealth=Mathf.Max(0,c.currentHealth-amount);if(c.currentHealth<=0){c.destroyed=true;CoreDestroyed?.Invoke(team);}} public void ResetCores(){foreach(var c in new[]{teamACore,teamBCore}){c.currentHealth=c.maxHealth;c.destroyed=false;}} } }